def pattern(n):
    if n <= 0:
        return ""
    max_length = 2 * n - 1
    result = []
    for i in range(n):
        s = ''.join(str(x % 10) for x in range(1, i + 2)) + ''.join(str(x % 10) for x in range(i, 0, -1))
        result.append(s.center(max_length))
    for i in range(n - 2, -1, -1):
        result.append(result[i])
    return '\n'.join(result)
